/**
 * VigletLogo — product mark.
 *
 * Each product is an isometric cube in its colour, its front-top corner cut in the
 * angle of the Viglet V, with the element symbol (Du / Sh / Tu) on its left face.
 * The SVGs in public/logos/ are generated by make_marks.py in the alegauss/visibility
 * repository (marca/logo/), where the geometry is documented; copy them over after
 * regenerating, do not edit them by hand.
 *
 * Size modes
 * ──────────
 * size < 56   → the cube alone (<id>-small.svg): below that the symbol stops reading
 * size ≥ 56   → the cube with the symbol (<id>.svg)
 */

export const PRODUCT_COLORS: Record<string, string> = {
  dumont: '#0F766E',  // teal
  shio:   '#7C3AED',  // violet
  turing: '#4169E1',  // royalblue
}

const PRODUCT_NAMES: Record<string, string> = {
  dumont: 'Viglet Dumont',
  shio:   'Viglet Shio',
  turing: 'Viglet Turing',
}

interface VigletLogoProps {
  readonly identifier: string
  readonly size?: number
  /** Animate a soft coloured glow around the cube (hero sizes). Default true. */
  readonly glow?: boolean
  readonly className?: string
}

export default function VigletLogo({ identifier, size = 48, glow = true, className }: VigletLogoProps) {
  const name = PRODUCT_NAMES[identifier]
  if (!name) return null
  const small = size < 56
  const classes = [className, glow && !small ? 'vg-cube-glow' : ''].filter(Boolean).join(' ')
  return (
    <img
      src={`/logos/${identifier}${small ? '-small' : ''}.svg`}
      alt={name}
      width={size}
      height={size}
      className={classes || undefined}
      style={{ flexShrink: 0, userSelect: 'none' }}
      draggable={false}
    />
  )
}
